  'event.requestAccepted': ['Accepted by {shop}', '{shop} ने स्वीकार किया', '{shop} ने स्वीकारली', '{shop} গ্রহণ করেছে', '{shop} ஏற்றுக்கொண்டது'],
  'event.requestNoMatch': ['Every technician declined', 'सभी मिस्त्रियों ने मना किया', 'सर्व मिस्त्रींनी नकार दिला', 'সব মিস্ত্রি না বলেছেন', 'அனைத்து மெக்கானிக்குகளும் மறுத்தனர்'],
