const idx = (lang) => Math.max(0, LANG_CODES.indexOf(lang));
const label = (obj, lang) => (obj == null ? '' : typeof obj === 'string' ? obj : obj[lang] || obj.en || '');

// Typed reference → text in `lang`. Plain strings and numbers pass through.
export function resolveParam(v, lang = 'en') {
  if (v == null || typeof v !== 'object') return v ?? '';
  if (Array.isArray(v)) return v.map((x) => resolveParam(x, lang)).join(', ');
  if ('msg' in v) return format(v.msg, v.params || {}, lang);
  if ('comp' in v) {
    const [cat, comp] = v.comp;
    return label(CATEGORIES[cat]?.components.find((x) => x.id === comp), lang) || comp;
  }
  if ('cat' in v) return label(CATEGORIES[v.cat], lang) || v.cat;
  if ('cause' in v) return label(CAUSES[v.cause], lang) || v.cause;
  if ('sev' in v) return label(SEVERITY[v.sev], lang) || v.sev;
  if ('spare' in v) return label(SPARE[v.spare], lang) || v.spare;
  if ('barrier' in v) return label(BARRIERS[v.barrier], lang) || v.barrier;
  if ('gate' in v) return label(GATES[v.gate], lang) || v.gate;
  if ('area' in v) return AREAS[v.area] ? label(AREAS[v.area].name, lang) : format(v.area ? 'area.code' : 'area.unknown', { code: v.area }, lang);
  if ('opt' in v) return format(`opt.${v.opt}`, {}, lang);
  if ('status' in v) return MSG[`status.${v.status}`] ? format(`status.${v.status}`, {}, lang) : v.status;
  if ('money' in v) return `₹${Math.round(Number(v.money) || 0).toLocaleString('en-IN')}`;
  if ('kg' in v) return `${(Math.round((Number(v.kg) || 0) * 10) / 10).toLocaleString('en-IN')} kg`;
  if ('date' in v) {
    try { return new Intl.DateTimeFormat(`${lang === 'en' ? 'en-IN' : `${lang}-IN`}-u-nu-latn`, { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(v.date)); }
    catch { return String(v.date).slice(0, 10); }
  }
  return '';
}

/** MSG[key] in `lang` (English fallback, then the key), with {placeholders} filled from params. */
export function format(key, params = {}, lang = 'en') {
  const tuple = MSG[key];
  if (!tuple) return key;
  let s = tuple[idx(lang)] || tuple[0];
  if (s && typeof s === 'object') {
    let cat = 'other';
    try { cat = new Intl.PluralRules(lang).select(Number(params.n)); } catch { /* keep 'other' */ }
    s = s[cat] ?? s.other ?? Object.values(s)[0];
  }
  return String(s).replace(/\{(\w+)\}/g, (m, k) => (k in params ? String(resolveParam(params[k], lang)) : m));
}
